-- #963 (lane b): creatures spawned with MovementType 2 (waypoint) but no path
-- ("WaypointMovementGenerator::LoadPath: creature X doesn't have waypoint path id: N", 22+3 lines per boot).
-- Method: each of our spawns was matched by entry + map + position against AzerothCore acore_world (local copy,
-- 2026-10-28), TrinityCore TDB_full_world_335.26091 (2026-09-09), CPP TDB_full_world_434.22011 (2022-01-09) and
-- SkyFire SFDB_full_548_26.002 (2026-08-18) (script (not shipped).
--  (a) Same spawn (0-1.2 yd; Azurous 36.8 yd, same patrol) has a waypoint path in AC -> port AC waypoint_data,
--      path id = our spawn guid (this DB's convention), creature_addon.path_id set. AC waypoint actions (587010 pt15
--      action 70, 965920 pt8 action 455) point to AC waypoint_scripts ids that do not exist here -> action 0.
--      AC path -> our guid: 774800->13388 Grimungous, 18140->52901 Thief Catcher Thunderbrew, 587010->67443 Novice Ranger,
--      965920->72498 Harbinger Haronem, 2090770/2090760/2090750->399981/399982/399983 Gjalerhorn Scavenger,
--      518900->52639 (and 302670, the second Azurous spawn on the same spot) Azurous.
--  (b) Same spawn is stationary (MovementType 0) in AC/TC 335/CPP 434/SkyFire and no source has a path, or no source has
--      the spawn at all (Cataclysm-moved spawns) -> MovementType 0 (stops the error; the creature stood still anyway,
--      because the waypoint generator fails without a path).
-- Undo: DELETE FROM waypoint_data WHERE id IN (13388,52901,67443,72498,399981,399982,399983,52639);
--       restore MovementType 2 for the (b) guids and the old creature_addon.path_id values (67443->67443, 72498->72498 kept).

DELETE FROM `waypoint_data` WHERE `id` IN (13388,52901,67443,72498,399981,399982,399983,52639);

ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
UPDATE `creature` SET `MovementType`=2 WHERE `guid` IN (13388,52901,67443,72498,399981,399982,399983,52639,302670);

-- (b) no path anywhere / stationary in every source
UPDATE `creature` SET `MovementType`=0 WHERE `guid` IN
 (65763,74230,74231,67447,68292,73637,175727,175852,175855,51540,  -- stationary in AC/TC335/CPP434/SkyFire at the same spot
  11304,73715,175823,175826,175829,175883,175884);                 -- no matching spawn in any source (moved in Cataclysm)
UPDATE `creature_addon` SET `path_id`=0 WHERE `guid` IN (65763,74230,74231,67447,68292,73637,175727,175852,175855,51540,11304,73715,175823,175826,175829,175883,175884);
